reviewer_commands:
jq -c '
def scalar($v): if ($v|type) == "string" or ($v|type) == "boolean" or ($v|type) == "number" or ($v|type) == "null" then $v else "__NONSCALAR__" end;
def matched($id): first(.. | objects | select((.scope_identity? == $id) or (.identity? == $id) or (.scope_id? == $id))) // {};
def projected($id): (matched($id)) as $m | {
  scope_identity: scalar($m.scope_identity), identity: scalar($m.identity), scope_id: scalar($m.scope_id),
  status: scalar($m.status), included: scalar($m.included), in_scope: scalar($m.in_scope),
  satisfied: scalar($m.satisfied), present: scalar($m.present), required: scalar($m.required),
  value: scalar($m.value), contract: scalar($m.contract), authority: scalar($m.authority), exports: scalar($m.exports)
};
{
  scope_identity: scalar(.scope_identity),
  required_scope_identities: (if (.required_scope_identities?|type) == "array" then {type:"array", length:(.required_scope_identities|length), has_contract:(.required_scope_identities|index("SCOPE-CONTRACT") != null), has_authority:(.required_scope_identities|index("SCOPE-AUTHORITY") != null), has_exports:(.required_scope_identities|index("SCOPE-EXPORTS") != null)} else {type:(.required_scope_identities?|type)} end),
  scope_contract: projected("SCOPE-CONTRACT"),
  scope_authority: projected("SCOPE-AUTHORITY"),
  scope_exports: projected("SCOPE-EXPORTS")
}' evaluation-fixture/paired-scope-evidence.json
